    return False

def expand_with_same_line(page, rect, extra_needles):
    r = fitz.Rect(rect)
    for needle in extra_needles:
        for tr in page.search_for(needle):
            if abs(tr.y0 - rect.y0) < 2 and tr.x0 >= rect.x0 - 1:
